class InputCell:
    def __init__(self, initial_value):
        self.value = initial_value
        self._dependents = set()

    def set_value(self, new_value):
        # If value didn't change, nothing to do.
        if self.value == new_value:
            return
        self.value = new_value

        # Collect transitive closure of affected compute cells
        affected = set()
        stack = list(self._dependents)
        while stack:
            cell = stack.pop()
            if cell in affected:
                continue
            affected.add(cell)
            stack.extend(cell._dependents)

        if not affected:
            return

        # Save previous values for callbacks decision
        previous_values = {cell: cell.value for cell in affected}

        # Topological sort (Kahn) among affected compute cells to compute in correct order
        # indegree = number of input dependencies that are in affected
        indegree = {}
        for cell in affected:
            cnt = 0
            for inp in cell.inputs:
                if isinstance(inp, ComputeCell) and inp in affected:
                    cnt += 1
            indegree[cell] = cnt

        # Start with nodes with indegree 0
        queue = [cell for cell, deg in indegree.items() if deg == 0]
        # We'll process nodes and compute new values
        processed_count = 0
        while queue:
            cell = queue.pop(0)
            # Compute new value
            vals = [inp.value for inp in cell.inputs]
            try:
                new_val = cell.compute_function(vals)
            except Exception:
                # If compute function errors, skip updating but still proceed
                new_val = cell.value
            cell.value = new_val
            processed_count += 1
            # Decrease indegree of dependents in affected
            for dep in cell._dependents:
                if dep in affected:
                    indegree[dep] -= 1
                    if indegree[dep] == 0:
                        queue.append(dep)

        # If graph had cycles among affected (shouldn't in valid use), some nodes unprocessed.
        # In that case, we won't call their callbacks because stable state undefined.

        # After computing final values, call callbacks for compute cells whose value changed
        for cell in affected:
            old = previous_values.get(cell)
            new = cell.value
            if old != new:
                for cb in list(cell._callbacks):
                    try:
                        cb(new)
                    except Exception:
                        pass


class ComputeCell:
    def __init__(self, inputs, compute_function):
        self.inputs = list(inputs)
        self.compute_function = compute_function
        self._callbacks = []
        self._dependents = set()

        # Register self as dependent on inputs
        for inp in self.inputs:
            if not hasattr(inp, "_dependents"):
                inp._dependents = set()
            inp._dependents.add(self)

        # Compute initial value
        vals = [inp.value for inp in self.inputs]
        self.value = compute_function(vals)

    def add_callback(self, callback):
        if callback not in self._callbacks:
            self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)
